INSERT INTO expenses (date, supplier, invoice_number, description, amount, btw_percentage, btw_amount, total, ledger_account_id)
SELECT '{{ $json.datum }}', '{{ $json.leverancier }}', '{{ $json.factuurnummer }}', '{{ $json.omschrijving }}', {{ $json.bedrag }}, {{ $json.btw_pct }}, {{ $json.btw_bedrag }}, {{ $json.totaal }}, id
FROM ledger_accounts WHERE code = SUBSTRING_INDEX('{{ $json.grootboek }}', ' ', 1) LIMIT 1;

INSERT INTO ledger_entries (date, account_id, description, debit, credit, reference, journal)
SELECT '{{ $json.datum }}', id, '{{ $json.omschrijving }}', {{ $json.bedrag }}, 0, '{{ $json.factuurnummer }}', 'inkoop'
FROM ledger_accounts WHERE code = SUBSTRING_INDEX('{{ $json.grootboek }}', ' ', 1) LIMIT 1;

